SELECT 0 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json_set(json('{}'),'$.transition_id',source.transition_id,'$.telegram_id',source.telegram_id,'$.from_plan',source.from_plan,'$.from_billing_mode',source.from_billing_mode,'$.to_plan',source.to_plan,'$.to_billing_mode',source.to_billing_mode,'$.target_package_code',source.target_package_code,'$.target_price_id',source.target_price_id,'$.target_price_version',source.target_price_version,'$.period_seconds',source.period_seconds,'$.offer_version',source.offer_version,'$.campaign_code',source.campaign_code,'$.source_paid_until',source.source_paid_until,'$.effective_at',source.effective_at,'$.state',source.state),'$.revision',source.revision,'$.target_order_id',source.target_order_id,'$.target_period_id',source.target_period_id,'$.target_grant_id',source.target_grant_id,'$.source_payment_ledger_entry_id',source.source_payment_ledger_entry_id) AS snapshot FROM (SELECT transition_id,telegram_id,from_plan,from_billing_mode,to_plan,to_billing_mode,target_package_code,target_price_id,target_price_version,period_seconds,offer_version,campaign_code,source_paid_until,effective_at,state,revision,target_order_id,target_period_id,target_grant_id,source_payment_ledger_entry_id FROM subscription_plan_transitions
  WHERE telegram_id=? ORDER BY effective_at DESC,transition_id LIMIT 129) AS source)) AS snapshot UNION ALL SELECT 1 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json_set(json('{}'),'$.transition_id',source.transition_id,'$.order_id',source.order_id,'$.plan_code',source.plan_code,'$.price_id',source.price_id,'$.price_version',source.price_version,'$.currency',source.currency,'$.amount_stars',source.amount_stars,'$.period_seconds',source.period_seconds,'$.order_state',source.order_state,'$.expires_at',source.expires_at,'$.terms_revision',source.terms_revision,'$.precheckout_approved_at',source.precheckout_approved_at,'$.invoice_state',source.invoice_state,'$.invoice_url',source.invoice_url,'$.payment_recorded',source.payment_recorded),'$.payment_accepted',source.payment_accepted,'$.cancellation_blocked',source.cancellation_blocked) AS snapshot FROM (SELECT m.transition_id,m.order_id,m.plan_code,m.price_id,m.price_version,m.currency,m.amount_stars,
  m.period_seconds,o.order_state,o.expires_at,o.terms_revision,o.precheckout_approved_at,
  r.state AS invoice_state,r.invoice_url,
  EXISTS(SELECT 1 FROM payment_ledger p WHERE p.order_id=o.order_id AND p.entry_type='payment') AS payment_recorded,
  EXISTS(SELECT 1 FROM payment_events e WHERE e.order_id=o.order_id AND e.outcome='accepted'
    AND e.event_type IN ('precheckout_received','precheckout_approved','successful_payment_received','payment_recorded','access_applied')) AS payment_accepted,
  EXISTS(SELECT 1 FROM subscription_billing_contracts c WHERE c.origin_order_id=o.order_id AND NOT(c.provider_state='unconfirmed'
    AND c.first_payment_ledger_entry_id IS NULL AND c.retired_at IS NULL
    AND NOT EXISTS(SELECT 1 FROM subscription_provider_commands cmd WHERE cmd.contract_id=c.contract_id)
    AND EXISTS(SELECT 1 FROM subscription_invoice_requests request WHERE request.contract_id=c.contract_id
      AND request.origin_order_id=o.order_id AND request.telegram_id=m.telegram_id AND request.attempted_count=1
      AND request.state IN ('confirmed','rejected')))) AS cancellation_blocked
  FROM subscription_package_orders m JOIN subscription_orders o ON o.order_id=m.order_id
  LEFT JOIN subscription_invoice_requests r ON r.origin_order_id=o.order_id AND r.telegram_id=m.telegram_id
  WHERE m.telegram_id=? AND m.billing_mode='recurring' AND m.transition_id IS NOT NULL ORDER BY m.order_id LIMIT 129) AS source)) AS snapshot UNION ALL SELECT 2 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json('{}'),'$.transition_id',source.transition_id) AS snapshot FROM (SELECT t.transition_id FROM subscription_plan_transitions t JOIN payment_ledger p
  ON p.related_ledger_entry_id=t.source_payment_ledger_entry_id AND p.telegram_id=t.telegram_id
  WHERE t.telegram_id=? AND p.entry_type IN ('refund','chargeback') ORDER BY t.transition_id LIMIT 129) AS source)) AS snapshot UNION ALL SELECT 3 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json_set(json_set(json('{}'),'$.state',source.state,'$.attempted_count',source.attempted_count,'$.request_sha256',source.request_sha256,'$.provider_result_sha256',source.provider_result_sha256,'$.invoice_url',source.invoice_url,'$.package_code',source.package_code,'$.duration_days',source.duration_days,'$.period_seconds',source.period_seconds,'$.quoted_starts_at',source.quoted_starts_at,'$.quoted_ends_at',source.quoted_ends_at,'$.price_id',source.price_id,'$.price_version',source.price_version,'$.plan_code',source.plan_code,'$.currency',source.currency,'$.amount_stars',source.amount_stars),'$.offer_version',source.offer_version,'$.campaign_code',source.campaign_code,'$.order_id',source.order_id,'$.invoice_payload',source.invoice_payload,'$.order_state',source.order_state,'$.created_at',source.created_at,'$.expires_at',source.expires_at,'$.terms_revision',source.terms_revision,'$.order_price_id',source.order_price_id,'$.order_price_version',source.order_price_version,'$.order_plan_code',source.order_plan_code,'$.order_currency',source.order_currency,'$.order_amount_stars',source.order_amount_stars,'$.order_access_seconds',source.order_access_seconds,'$.order_billing_mode',source.order_billing_mode),'$.canonical_price_id',source.canonical_price_id,'$.canonical_price_version',source.canonical_price_version,'$.canonical_plan_code',source.canonical_plan_code,'$.canonical_currency',source.canonical_currency,'$.canonical_amount_stars',source.canonical_amount_stars,'$.canonical_terms_revision',source.canonical_terms_revision,'$.access_seconds',source.access_seconds,'$.billing_mode',source.billing_mode,'$.publication_state',source.publication_state,'$.valid_from',source.valid_from,'$.valid_until',source.valid_until) AS snapshot FROM (SELECT r.state,r.attempted_count,r.request_sha256,r.provider_result_sha256,r.invoice_url,
  m.package_code,m.duration_days,m.period_seconds,m.quoted_starts_at,m.quoted_ends_at,m.price_id,m.price_version,
  m.plan_code,m.currency,m.amount_stars,m.offer_version,m.campaign_code,o.order_id,o.invoice_payload,o.order_state,
  o.created_at,o.expires_at,o.terms_revision,o.price_id AS order_price_id,o.price_version AS order_price_version,
  o.plan_code AS order_plan_code,o.currency AS order_currency,o.amount_stars AS order_amount_stars,
  o.access_seconds AS order_access_seconds,o.billing_mode AS order_billing_mode,
  p.price_id AS canonical_price_id,p.price_version AS canonical_price_version,p.plan_code AS canonical_plan_code,
  p.currency AS canonical_currency,p.amount_stars AS canonical_amount_stars,p.terms_revision AS canonical_terms_revision,
  p.access_seconds,p.billing_mode,p.publication_state,p.valid_from,p.valid_until
  FROM subscription_package_invoice_requests r JOIN subscription_package_orders m ON m.order_id=r.order_id
  JOIN subscription_orders o ON o.order_id=m.order_id JOIN price_book p ON p.price_id=m.price_id
  WHERE r.telegram_id=? AND m.telegram_id=r.telegram_id AND o.telegram_id=r.telegram_id AND m.billing_mode='prepaid'
    AND r.state IN ('admitted','attempted','confirmed','unknown')
    AND NOT EXISTS(SELECT 1 FROM payment_ledger paid WHERE paid.order_id=o.order_id AND paid.entry_type='payment')
  ORDER BY r.created_at DESC,r.request_id LIMIT 129) AS source)) AS snapshot UNION ALL SELECT 4 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json('{}'),'$.count',source.count) AS snapshot FROM (SELECT COUNT(*) AS count FROM subscription_orders WHERE telegram_id=? AND (order_state = 'paid' OR (order_state IN ('created', 'precheckout_ok') AND expires_at > ?))) AS source)) AS snapshot UNION ALL SELECT 5 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json('{}'),'$.terms_revision',source.terms_revision) AS snapshot FROM (SELECT terms_revision FROM terms_acceptances WHERE telegram_id=?
    AND acceptance_scope='stars_purchase' AND accepted_at<=? ORDER BY terms_revision LIMIT 129) AS source)) AS snapshot UNION ALL SELECT 6 AS position,(SELECT COALESCE(json_group_array(json(snapshot)),'[]') FROM
        (SELECT json_set(json('{}'),'$.price_version',source.price_version,'$.plan_code',source.plan_code,'$.amount_stars',source.amount_stars,'$.terms_revision',source.terms_revision) AS snapshot FROM (SELECT price_version,plan_code,amount_stars,terms_revision FROM price_book
    WHERE billing_mode='prepaid' AND access_seconds=? AND publication_state='approved' AND valid_from<=?
      AND (valid_until IS NULL OR valid_until>?) ORDER BY price_id LIMIT 129) AS source)) AS snapshot